input.oldString:
function draw() {
  ctx.clearRect(0, 0, width, height);
  // ground line
  ctx.fillStyle = '#654';
  ctx.fillRect(0, height - 10, width, 10);
  // player
  player.draw();
  // obstacles
  ctx.fillStyle = '#b33';
  obstacles.forEach(o => ctx.fillRect(o.x, o.y, o.w, o.h));
  // stars
  ctx.fillStyle = '#ff0';
  stars.forEach(s => {
    ctx.beginPath();
    ctx.arc(s.x + s.r, s.y + s.r, s.r, 0, Math.PI * 2);
    ctx.fill();
  });
  // score
  ctx.fillStyle = '#fff';
  ctx.font = '20px sans-serif';
  ctx.fillText('Score: ' + score, 10, 30);
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, width, height);
    ctx.fillStyle = '#f44';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', width/2, height/2);
  }
}

input.newString:
function draw() {
  ctx.clearRect(0, 0, width, height);
  // sky background
  ctx.fillStyle = skyGradient;
  ctx.fillRect(0, 0, width, height);
  // clouds
  ctx.fillStyle = 'rgba(255,255,255,0.8)';
  clouds.forEach(c => {
    ctx.beginPath();
    ctx.arc(c.x + c.size/2, c.y + c.size/2, c.size/2, 0, Math.PI * 2);
    ctx.fill();
  });
  // ground line
  ctx.fillStyle = '#654';
  ctx.fillRect(0, height - 10, width, 10);
  // player (draw as rounded character)
  ctx.fillStyle = '#0b8';
  ctx.beginPath();
  ctx.arc(player.x + player.w/2, player.y + player.h/2, player.w/2, 0, Math.PI * 2);
  ctx.fillRect(player.x, player.y, player.w, player.h); // keep rectangle base for collision
  // obstacles
  ctx.fillStyle = '#b33';
  obstacles.forEach(o => ctx.fillRect(o.x, o.y, o.w, o.h));
  // stars
  ctx.fillStyle = '#ff0';
  stars.forEach(s => {
    ctx.beginPath();
    ctx.arc(s.x + s.r, s.y + s.r, s.r, 0, Math.PI * 2);
    ctx.fill();
  });
  // score
  ctx.fillStyle = '#fff';
  ctx.font = '20px sans-serif';
  ctx.fillText('Score: ' + Math.floor(score), 10, 30);
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, width, height);
    ctx.fillStyle = '#f44';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', width/2, height/2);
  }
}

